/**
 * Compile-time static Protobuf types from proto/chat_realtime.proto.
 *
 * Uses pbjs/pbts static code generation instead of runtime .proto parsing.
 * Generated by scripts/generate-proto.sh — regenerate with: npm run generate-proto
 */

import type * as protobuf from 'protobufjs';
import { chat } from './chat_realtime_pb';

const v1 = chat.realtime.v1;

// ---------------------------------------------------------------------------
// loadProto() — backward-compatible shim for shared/utils/protobuf.ts
// Returns a minimal Root-like object with lookupType() that delegates
// to the statically generated message classes (zero runtime parsing).
// ---------------------------------------------------------------------------

const typeRegistry: Record<string, unknown> = {
  'chat.realtime.v1.RealtimeEvent': v1.RealtimeEvent,
  'chat.realtime.v1.MessageCreatedPayload': v1.MessageCreatedPayload,
  'chat.realtime.v1.ConversationCreatedPayload': v1.ConversationCreatedPayload,
  'chat.realtime.v1.ConversationUpdatedPayload': v1.ConversationUpdatedPayload,
  'chat.realtime.v1.TypingUpdatedPayload': v1.TypingUpdatedPayload,
  'chat.realtime.v1.User': v1.User,
  'chat.realtime.v1.Message': v1.Message,
  'chat.realtime.v1.Conversation': v1.Conversation,
  'chat.realtime.v1.MessagePreview': v1.MessagePreview,
  'chat.realtime.v1.MessageQuote': v1.MessageQuote,
};

const fakeRoot = {
  lookupType(name: string) {
    const type = typeRegistry[name];
    if (!type) throw new Error(`Type not found: ${name}`);
    return type;
  },
};

export function loadProto(): protobuf.Root {
  return fakeRoot as unknown as protobuf.Root;
}

// ---------------------------------------------------------------------------
// Enum const objects — compatible with `erasableSyntaxOnly: true`
// ---------------------------------------------------------------------------

export const RealtimeEventType = {
  REALTIME_EVENT_TYPE_UNSPECIFIED: 0,
  MESSAGE_CREATED: 1,
  CONVERSATION_CREATED: 2,
  CONVERSATION_UPDATED: 3,
  TYPING_UPDATED: 4,
} as const;
export type RealtimeEventType =
  (typeof RealtimeEventType)[keyof typeof RealtimeEventType];

export const ConversationType = {
  CONVERSATION_TYPE_UNSPECIFIED: 0,
  GROUP: 1,
  DIRECT: 2,
} as const;
export type ConversationType =
  (typeof ConversationType)[keyof typeof ConversationType];

export const MessageType = {
  MESSAGE_TYPE_UNSPECIFIED: 0,
  TEXT: 1,
} as const;
export type MessageType = (typeof MessageType)[keyof typeof MessageType];

// ---------------------------------------------------------------------------
// TypeScript interfaces — match the proto message shapes (camelCase)
// ---------------------------------------------------------------------------

export interface User {
  id: string;
  username: string;
  name: string;
  avatarUrl?: string;
  title?: string;
}

export interface MessagePreview {
  id: string;
  conversationId: string;
  sender?: User;
  body: string;
  type: MessageType;
  createdAt: string;
}

export interface MessageQuote {
  id: string;
  sender?: User;
  body: string;
  type: MessageType;
  createdAt: string;
}

export interface Message {
  id: string;
  conversationId: string;
  sender?: User;
  type: MessageType;
  body: string;
  quoteMessage?: MessageQuote;
  mentions: User[];
  createdAt: string;
  updatedAt: string;
}

export interface Conversation {
  id: string;
  name: string;
  type: ConversationType;
  avatarUrls: string[];
  memberCount: number;
  unreadCount: number;
  mentionCount: number;
  lastMessage?: MessagePreview;
  createdAt: string;
  updatedAt: string;
}

export interface MessageCreatedPayload {
  message?: Message;
}

export interface ConversationCreatedPayload {
  conversation?: Conversation;
}

export interface ConversationUpdatedPayload {
  conversation?: Conversation;
}

export interface TypingUpdatedPayload {
  conversationId: string;
  user?: User;
  isTyping: boolean;
}

export interface RealtimeEvent {
  eventId: string;
  type: RealtimeEventType;
  emittedAt: string;
  messageCreated?: MessageCreatedPayload;
  conversationCreated?: ConversationCreatedPayload;
  conversationUpdated?: ConversationUpdatedPayload;
  typingUpdated?: TypingUpdatedPayload;
}
